INSERT INTO drug (id, drug_name, generic_name, category, summary, indications, dosage, side_effects, contraindications, precautions, storage, max_single_dose, max_dose_unit) VALUES
(1,  '阿莫西林胶囊',       '阿莫西林',       '抗生素',     '适用于敏感菌引起的呼吸道、泌尿生殖道等感染', '适用于敏感菌（不产β内酰胺酶菌株）引起的呼吸道感染、泌尿生殖道感染、皮肤软组织感染等。', '成人一次0.5g，每6～8小时1次；小儿一日剂量按体重20～40mg/kg，每8小时1次。', '恶心、呕吐、腹泻及假膜性肠炎等胃肠道反应；皮疹、药物热和哮喘等过敏反应。', '对青霉素类药物过敏者禁用；传染性单核细胞增多症患者禁用。', '肾功能不全者需根据肌酐清除率调整剂量；有哮喘、枯草热等过敏性疾病史者慎用。', '密封，在阴凉干燥处保存（不超过20℃）。', 0.50, 'g'),
(2,  '阿莫西林克拉维酸钾片', '阿莫西林克拉维酸钾', '抗生素', '复方制剂，用于产酶耐药菌感染', '用于敏感菌引起的呼吸道、泌尿道等感染，尤其对产β-内酰胺酶的耐药菌株有效。', '成人一次0.5g（以阿莫西林计），每8小时1次。', '腹泻、恶心、皮疹；罕见肝酶升高。', '青霉素过敏者禁用；传染性单核细胞增多症患者禁用。', '严重肝功能不全者慎用。', '密封，凉暗处保存。', 0.50, 'g'),
(3,  '布洛芬缓释胶囊',     '布洛芬',         '解热镇痛',   '用于缓解轻至中度疼痛及退热', '用于缓解头痛、关节痛、牙痛、肌肉痛等轻至中度疼痛，也可用于普通感冒或流感引起的发热。', '成人一次0.3g，每12小时1次，整粒吞服。', '胃肠道不适、恶心、头晕；长期使用可致消化道溃疡。', '对阿司匹林过敏者禁用；活动性消化道溃疡患者禁用；孕妇及哺乳期妇女禁用。', '饭后服用可减轻胃部刺激；连续使用不得超过5天。', '密封，阴凉干燥处保存。', 0.30, 'g'),
(4,  '布洛芬片',           '布洛芬',         '解热镇痛',   '用于缓解轻至中度疼痛及退热', '用于缓解轻至中度疼痛如头痛、关节痛、偏头痛、牙痛、肌肉痛、神经痛，也用于普通感冒或流行性感冒引起的发热。', '成人一次0.2~0.4g，每4~6小时1次，24小时内不超过4次。', '恶心、呕吐、胃烧灼感；少见皮疹、耳鸣。', '对本品及其他非甾体抗炎药过敏者禁用；严重肝肾功能不全者禁用。', '不宜长期服用；服药期间不得饮酒。', '密封保存。', 0.40, 'g'),
(5,  '氯雷他定片',         '氯雷他定',       '抗过敏',     '用于缓解过敏性鼻炎及荨麻疹症状', '用于缓解过敏性鼻炎有关的症状，如喷嚏、流涕、鼻痒、鼻塞以及眼部痒及烧灼感；亦用于缓解慢性荨麻疹症状。', '成人及12岁以上儿童一次10mg，每日1次。', '乏力、头痛、嗜睡、口干等，发生率低。', '对本品过敏者禁用。', '严重肝功能不全者需减量；驾驶或操作机器时需谨慎。', '遮光，密封保存。', 10.00, 'mg'),
(6,  '蒙脱石散',           '蒙脱石',         '止泻',       '用于成人及儿童急、慢性腹泻', '用于成人及儿童急、慢性腹泻；用于食道、胃、十二指肠疾病引起的相关疼痛症状的辅助治疗。', '成人一次1袋（3g），每日3次，倒入温水中混匀服用。', '偶见便秘，大便干结。', '对本品过敏者禁用。', '治疗急性腹泻时应注意纠正脱水；与其他药物间隔1小时以上服用。', '密封保存。', 3.00, 'g'),
(7,  '阿司匹林肠溶片',     '阿司匹林',       '抗血小板',   '用于心脑血管疾病的预防', '用于不稳定心绞痛、急性心肌梗死、脑梗死等心脑血管疾病的二级预防。', '一次100mg，每日1次，餐前整片吞服。', '胃肠道出血、消化性溃疡；过敏反应；肝肾功能损害。', '活动性消化性溃疡或出血者禁用；对阿司匹林过敏者禁用；儿童禁用（瑞氏综合征风险）。', '避免与酒同服；手术前应告知医生正在服用本药。', '密封，阴凉处保存。', 100.00, 'mg'),
(8,  '硝苯地平缓释片',     '硝苯地平',       '降压药',     '用于高血压、心绞痛的治疗', '用于高血压、冠心病心绞痛的治疗。', '一次30mg，每日1次，整片吞服不可掰开。', '头痛、面部潮红、心悸、下肢水肿。', '对硝苯地平过敏者禁用；心源性休克患者禁用。', '低血压患者慎用；服用期间避免饮用葡萄柚汁。', '遮光，密封保存。', 30.00, 'mg'),
(9,  '二甲双胍片',         '二甲双胍',       '降糖药',     '用于2型糖尿病的治疗', '用于单纯饮食控制不满意的2型糖尿病病人，特别是肥胖和伴高胰岛素血症者。', '一次0.5g，每日2~3次，餐中或餐后服用。', '恶心、呕吐、腹泻、口中金属味；罕见乳酸酸中毒。', '肾功能不全、酗酒者、充血性心力衰竭患者禁用。', '定期监测肾功能；用药期间避免饮酒。', '密封保存。', 0.50, 'g'),
(10, '奥美拉唑肠溶胶囊',   '奥美拉唑',       '消化系统',   '用于胃溃疡、十二指肠溃疡及反流性食管炎', '用于胃溃疡、十二指肠溃疡、应激性溃疡、反流性食管炎和卓-艾综合征。', '一次20mg，每日1次，晨起空腹吞服。', '头痛、腹泻、恶心；长期使用需警惕骨质疏松风险。', '对本品过敏者禁用；与克拉霉素等药物存在相互作用。', '长期服用（超过1年）需在医生指导下进行。', '密封，凉暗处保存。', 20.00, 'mg'),
(11, '头孢呋辛酯片',       '头孢呋辛酯',     '抗生素',     '用于敏感菌引起的呼吸道、泌尿道感染', '用于敏感菌引起的上呼吸道感染、下呼吸道感染、泌尿道感染、皮肤软组织感染等。', '成人一次0.25g~0.5g，每日2次，餐后服用。', '腹泻、恶心、皮疹；少见伪膜性肠炎。', '对头孢菌素类过敏者禁用；青霉素过敏者慎用。', '服药期间及停药一周内禁止饮酒（双硫仑样反应）。', '密封，凉暗处保存。', 0.50, 'g'),
(12, '藿香正气水',         '藿香正气',       '中成药',     '解表化湿，理气和中', '用于外感风寒、内伤湿滞或夏伤暑湿所致的感冒，症见头痛昏重、脘腹胀痛、呕吐泄泻。', '一次10ml，每日2次，口服。', '偶见恶心、呕吐；过敏体质者可能出现皮疹。', '孕妇禁用；对乙醇过敏者禁用。', '本药含乙醇，服药期间不得驾驶机、车、船，从事高空作业；忌与头孢类药物同服（双硫仑样反应）。', '密封，置阴凉处。', 10.00, 'ml'),
(13, '板蓝根颗粒',         '板蓝根',         '中成药',     '清热解毒，凉血利咽', '用于肺胃热盛所致的咽喉肿痛、口咽干燥；急性扁桃体炎见上述证候者。', '一次10g（1袋），每日3~4次，开水冲服。', '少见恶心、呕吐。', '对本品过敏者禁用；糖尿病患者慎用（含蔗糖）。', '服药期间忌烟酒、辛辣、鱼腥食物。', '密封保存。', 10.00, 'g'),
(14, '连花清瘟胶囊',       '连花清瘟',       '中成药',     '清瘟解毒，宣肺泄热', '用于流行性感冒属热毒袭肺证，症见发热或高热、恶寒、肌肉酸痛、鼻塞流涕、咳嗽、头痛、咽干咽痛。', '一次4粒，每日3次，口服。', '恶心、呕吐、腹泻；过敏性皮疹。', '对本品过敏者禁用；风寒感冒者不适用。', '高血压、心脏病患者慎用；服药期间忌烟酒及辛辣食物。', '密封，置阴凉干燥处。', 1.20, 'g'),
(15, '维生素C片',          '维生素C',        '维生素',     '补充维生素C，增强免疫力', '用于预防和治疗坏血病，也可用于各种急慢性传染性疾病及紫癜等的辅助治疗。', '一次0.1g，每日1~3次，口服。', '长期过量服用可致泌尿系结石、腹泻。', '对本品过敏者禁用。', '不宜长期过量服用；痛风、尿路结石患者慎用。', '遮光，密封保存。', 0.10, 'g');
INSERT INTO hospital (id, name, address, phone, rating, level, longitude, latitude, introduction) VALUES
(1, '广州市第一人民医院',   '广州市越秀区盘福路1号',       '020-81048888', 4.5, '三甲', 113.263200, 23.129000, '广州市第一人民医院始建于1899年，是广州市属最大的综合性三级甲等医院，设有内科、急诊科、心血管内科等重点科室，拥有先进的抢救设备与24小时急诊服务。'),
(2, '广东省人民医院',       '广州市越秀区中山二路106号',   '020-83827812', 4.7, '三甲', 113.279600, 23.122000, '广东省人民医院创建于1946年，是华南地区规模最大的综合性医院之一，呼吸内科、心内科、内分泌科为优势学科。'),
(3, '中山大学附属第一医院', '广州市越秀区中山二路58号',    '020-87755766', 4.8, '三甲', 113.282000, 23.120000, '中山大学附属第一医院是国家重点建设的综合性医院，心血管、神经、消化等专科实力位居全国前列。'),
(4, '广东省中医院',         '广州市越秀区大德路111号',     '020-81887233', 4.6, '三甲', 113.258000, 23.125000, '广东省中医院是全国规模最大的中医医院之一，中医内科、针灸科等特色专科享有盛誉。'),
(5, '广州市妇女儿童医疗中心','广州市天河区金穗路9号',       '020-38076301', 4.6, '三甲', 113.330000, 23.126000, '广州市妇女儿童医疗中心是华南地区规模最大的妇儿专科医院，妇产科、儿科为优势学科。'),
(6, '南方医科大学南方医院', '广州市白云区广州大道北1838号', '020-61641888', 4.7, '三甲', 113.310000, 23.180000, '南方医院是集医疗、教学、科研于一体的大型综合性医院，骨科、肾内科等为国家重点学科。'),
(7, '广州中医药大学第一附属医院', '广州市白云区机场路16号', '020-36591158', 4.5, '三甲', 113.276000, 23.170000, '广州中医药大学第一附属医院是国家中医临床研究基地，中医骨伤科、针灸科特色突出。'),
(8, '广州市番禺区人民医院', '广州市番禺区市桥街桥东路93号', '020-84826611', 4.2, '二甲', 113.365000, 22.935000, '广州市番禺区人民医院是番禺区最大的综合性二级甲等医院，设有内科、骨科、妇产科等科室，服务覆盖番禺及周边地区。'),
(9, '广州市红十字会医院',   '广州市海珠区同福中路396号',   '020-84412233', 4.3, '三甲', 113.258000, 23.097000, '广州市红十字会医院是海珠区主要的综合性医院，骨科、烧伤科为特色专科。');
