INSERT INTO article (id, title, summary, content, cover_image, category, author, author_title, tags, read_count, like_count, collect_count, share_count, publish_time) VALUES
(1, '高血压患者冬季用药指南', '冬季气温降低，高血压患者需要注意什么？本文详细介绍了冬季用药的注意事项。', '冬季气温降低，人体血管收缩，血压容易升高。高血压患者冬季需要注意以下几点：\n\n一、按时服药\n冬季血压容易波动，患者应严格按照医嘱服药，不可自行增减剂量。建议每日定时测量血压并记录。\n\n二、注意保暖\n寒冷刺激会导致血管收缩，出门应做好头部和颈部保暖，避免清晨在寒冷环境停留过久。\n\n三、饮食清淡\n冬季进补要适度，避免高盐高脂饮食，每日食盐摄入量控制在5克以内。\n\n四、适度运动\n选择阳光充足的时段进行散步等温和运动，避免清晨空腹剧烈运动。\n\n五、定期复诊\n血压波动明显时应及时就医调整用药方案，切勿自行换药或停药。', NULL, '西药', '张医生', '三甲医院心血管科主治医师', '高血压,冬季,用药安全', 1523, 89, 45, 12, '2026-07-10 08:00:00'),
(2, '高血压患者夏季注意事项', '夏季血压偏低，降压药要不要减量？专家教你科学应对。', '夏季气温升高，血管扩张，部分高血压患者的血压会有所下降。此时需要注意：\n\n一、监测血压\n夏季每日早晚各测量一次血压，连续记录一周，为医生调整用药提供依据。\n\n二、避免自行减药\n血压下降不等于可以停药，擅自减量可能导致血压反跳。调整用药需遵医嘱。\n\n三、补充水分\n高温出汗多，注意适量补水，但避免一次性大量饮水导致血容量骤增。\n\n四、防暑降温\n避免正午高温时段外出，空调温度不宜过低，室内外温差过大易诱发心血管事件。', NULL, '疾病', '李医生', '社区全科主治医师', '高血压,夏季,生活调理', 986, 42, 18, 5, '2026-07-08 09:00:00'),
(3, '中药调理脾胃的常见方法', '脾胃不和是很多中老年人的常见问题，本文整理了中药调理脾胃的几种常见方法。', '中医认为"脾胃为后天之本"，脾胃功能直接影响营养吸收与气血生化。常见调理方法：\n\n一、健脾食疗\n山药、薏米、莲子、芡实等食材煮粥，可健脾祛湿，适合日常调理。\n\n二、常用中成药\n香砂六君子丸健脾益气，参苓白术散健脾渗湿，保和丸消食导滞，需辨证选用。\n\n三、生活习惯\n三餐定时定量，细嚼慢咽，避免生冷油腻；饭后适当散步助消化。\n\n四、穴位保健\n足三里、中脘穴每日按揉3-5分钟，可健运脾胃。', NULL, '中药', '李药师', '执业中药师', '脾胃,中药,食疗', 987, 45, 22, 7, '2026-07-09 10:30:00'),
(4, '如何正确服用中药汤剂', '中药汤剂的服用方法直接影响药效，本文介绍了正确的煎煮和服用方法。', '中药汤剂的煎煮与服用方法直接影响药效发挥：\n\n一、煎煮器具\n首选砂锅、陶瓷锅，避免铁锅、铝锅（金属离子可能与药效成分发生反应）。\n\n二、煎煮方法\n药材冷水浸泡30分钟后武火煮沸，转文火煎煮20-30分钟，滤出药液；二煎加温水再煎15-20分钟，两次药液合并分服。\n\n三、服用时间\n补益药宜饭前服，对胃肠有刺激的药物宜饭后服，安神药宜睡前服。\n\n四、服用温度\n一般温服为宜，解表药可稍热服，清热药可凉服。', NULL, '中药', '王药师', '中药学硕士', '中药,煎煮,服用方法', 2341, 156, 89, 23, '2026-07-08 14:00:00'),
(5, '感冒了要不要吃抗生素', '感冒多是病毒感染，盲目吃抗生素不仅无效还可能有害，一文说清楚。', '很多人在感冒后习惯吃"消炎药"，实际上这是常见误区：\n\n一、感冒多为病毒性\n普通感冒90%以上由病毒引起，抗生素只对细菌感染有效，对病毒性感冒无效。\n\n二、滥用抗生素的危害\n长期滥用会导致菌群失调、耐药菌产生，真正需要抗生素时可能面临无药可用。\n\n三、什么情况需要就医\n持续高热超过3天、咳黄脓痰、出现胸痛或呼吸急促等症状，提示可能合并细菌感染，应及时就医。\n\n四、正确做法\n感冒以对症治疗为主：多休息、多饮水，遵医嘱使用退热药或缓解症状的药物。', NULL, '西药', '陈医生', '呼吸科副主任医师', '感冒,抗生素,合理用药', 1876, 98, 51, 15, '2026-07-07 11:00:00'),
(6, '老年人秋季养生指南', '秋季干燥，老年人养生重在润燥防病，五大要点请收好。', '秋季气候干燥，气温逐渐下降，老年人养生应注重以下要点：\n\n一、润肺防燥\n多食梨、百合、银耳、蜂蜜等润燥食物，少食辛辣煎炸之品。\n\n二、适度秋冻\n秋季不宜过早添厚衣，但早晚温差大，出门注意增减衣物，防止感冒。\n\n三、预防秋乏\n保证充足睡眠，午后小憩20-30分钟，避免熬夜。\n\n四、运动调养\n选择太极拳、八段锦等舒缓运动，锻炼时间以早晨日出后为宜。\n\n五、情绪平和\n秋易生悲，多参加社交活动，保持心情舒畅。', NULL, '养生', '刘营养师', '国家注册营养师', '秋季,养生,老年人', 1450, 76, 40, 9, '2026-07-06 08:30:00'),
(7, '失眠的中医调理', '中医如何看待失眠？从食疗到穴位按摩，给出系统的调理方案。', '中医认为失眠多与心脾两虚、肝郁化火、阴虚火旺等因素相关，调理讲究辨证论治：\n\n一、常见证型\n心脾两虚者多梦易醒、神疲乏力；肝郁化火者入睡困难、急躁易怒；阴虚火旺者心烦不寐、手足心热。\n\n二、食疗建议\n心脾两虚可食桂圆莲子粥；肝郁化火可饮玫瑰花茶；阴虚火旺可用酸枣仁煮水代茶饮。\n\n三、穴位按摩\n睡前按揉神门穴、安眠穴各3分钟，可宁心安神。\n\n四、生活习惯\n睡前1小时远离手机，保持卧室安静黑暗，固定作息时间。', NULL, '养生', '王药师', '执业中药师', '失眠,中医,安神', 1203, 88, 35, 11, '2026-07-05 20:00:00'),
(8, '高血脂人群饮食注意事项', '管住嘴才能降血脂，这份饮食清单请查收。', '高血脂人群饮食管理是控制血脂的基础，注意以下几点：\n\n一、限制饱和脂肪\n少吃肥肉、动物内脏、黄油等，选择鱼类、禽肉、豆制品等优质蛋白。\n\n二、增加膳食纤维\n燕麦、糙米、蔬菜、豆类富含可溶性膳食纤维，有助于降低胆固醇吸收。\n\n三、烹调方式\n多用蒸、煮、炖、凉拌，少用油炸、煎烤。食用油每日不超过25克。\n\n四、戒烟限酒\n吸烟和过量饮酒都会影响血脂代谢，应坚决戒除或严格限制。\n\n五、定期复查\n遵医嘱定期复查血脂四项，评估饮食控制效果。', NULL, '饮食', '刘营养师', '国家注册营养师', '高血脂,饮食,胆固醇', 1322, 61, 28, 8, '2026-07-04 09:00:00'),
(9, '糖尿病患者三餐怎么吃', '糖尿病患者不是不能吃，而是要会吃，三大餐次搭配全攻略。', '糖尿病患者合理饮食是控制血糖的基础，"管住嘴"不等于"饿肚子"：\n\n一、主食定量\n每餐主食控制在1-2两（生重），粗细搭配，增加全谷物比例。\n\n二、蛋白充足\n每餐保证适量优质蛋白：鸡蛋、鱼肉、瘦肉、豆制品轮换食用。\n\n三、蔬菜足量\n每餐蔬菜不少于半斤，深色蔬菜占一半以上。\n\n四、进餐顺序\n建议先喝汤、再吃蔬菜、然后吃蛋白类、最后吃主食，有助于平稳餐后血糖。\n\n五、加餐策略\n两餐之间如饥饿可加餐，选择无糖酸奶、黄瓜等低升糖食物。', NULL, '饮食', '赵医生', '内分泌科主治医师', '糖尿病,饮食,三餐', 1650, 73, 44, 14, '2026-07-03 12:00:00'),
(10, '儿童用药安全须知', '孩子生病用药，家长最容易犯的五个错误，务必看完。', '儿童用药安全关系到孩子的健康成长，以下错误家长应避免：\n\n一、成人药减半给孩子吃\n儿童不是缩小版的成人，肝肾功能发育不完善，必须使用儿童专用制剂。\n\n二、滥用退烧药\n体温超过38.5℃才考虑使用退热药，两次用药间隔不少于4-6小时，避免交替混用。\n\n三、抗生素随意停用\n抗生素需足量足疗程，随意停药易致耐药和病情反复。\n\n四、糖浆当饮料存放\n药品应放在儿童接触不到的高处，用后立即盖紧瓶盖。\n\n五、自行判断"见效慢"就加量\n剂量需按体重计算，加量可能导致中毒，用药3天无效应及时就医。', NULL, '疾病', '孙药师', '儿科临床药师', '儿童,用药安全,剂量', 2010, 112, 67, 19, '2026-07-02 15:00:00');
